# Example of dictionary and set initialization
user_data = {'name': 'Bob', 'age': 30}
unique_ids = {101, 102, 103}

# Example of a simple helper function
def display_info(item):
    print(f"Item: {item}")

# Example of a helper function with type-based operations
def show_operations(value):
    if isinstance(value, str):
        print(f"String operations: {value.upper()}, {value[::-1]}")
    elif isinstance(value, list):
        print(f"List operations: {value.append('new')}, {len(value)}")
